//! C2PA / Content Credentials detection.
//!
//! We use the reference C2PA reader for structure, but score the *claim*
//! itself: an invalid manifest can still state that an image was generated by
//! AI. Validation state is reported alongside the signal so a reviewer can
//! tell a cryptographically valid manifest from an unsigned one.

use crate::detect::Input;
use crate::model::{Confidence, Signal, Source};
use crate::patterns;
use c2pa::assertions::Actions;
use c2pa::{DigitalSourceType, Manifest, Reader, ValidationState};
use std::io::Cursor;
use std::sync::{Arc, OnceLock};

/// Quick pre-check: every C2PA manifest store contains JUMBF boxes. Do not
/// look for the string "c2pa" alone: it appears in ordinary XMP and would
/// send non-C2PA files through the parser.
fn may_have_c2pa(bytes: &[u8]) -> bool {
    memchr::memmem::find(bytes, b"jumb").is_some()
}

fn detector_context() -> &'static Arc<c2pa::Context> {
    static CONTEXT: OnceLock<Arc<c2pa::Context>> = OnceLock::new();
    CONTEXT.get_or_init(|| Arc::new(c2pa::Context::new()))
}

pub fn detect(input: &Input) -> Vec<Signal> {
    if input.mime.is_empty() || !may_have_c2pa(input.bytes) {
        return Vec::new();
    }
    let mime = input.mime.split(';').next().unwrap_or(input.mime);
    let reader = match Reader::from_shared_context(detector_context())
        .with_stream(mime, Cursor::new(input.bytes))
    {
        Ok(reader) => reader,
        Err(c2pa::Error::JumbfNotFound) | Err(c2pa::Error::UnsupportedType) => return Vec::new(),
        Err(_) => return Vec::new(),
    };
    let state = reader.validation_state();
    let state_label = validation_label(state);
    let mut signals = Vec::new();
    for manifest in reader.manifests().values() {
        check_manifest(manifest, state, state_label, &mut signals);
    }
    signals
}

fn validation_label(state: ValidationState) -> &'static str {
    match state {
        ValidationState::Valid => "valid",
        ValidationState::Trusted => "trusted",
        ValidationState::Invalid => "invalid",
    }
}

/// A valid manifest is stronger evidence than an unsigned/malformed one.
fn confidence_for(weight: u8, state: ValidationState) -> Confidence {
    let weight = if state == ValidationState::Invalid {
        weight.saturating_sub(30)
    } else {
        weight
    };
    if weight >= 80 {
        Confidence::High
    } else if weight >= 50 {
        Confidence::Medium
    } else {
        Confidence::Low
    }
}

fn check_manifest(
    manifest: &Manifest,
    state: ValidationState,
    state_label: &str,
    signals: &mut Vec<Signal>,
) {
    if let Some(generator) = manifest.claim_generator()
        && let Some((tool, matched)) = patterns::match_value(generator).first()
    {
        signals.push(
            Signal::new(
                Source::C2pa,
                confidence_for(85, state),
                "c2pa.claim_generator",
                patterns::truncate(
                    &format!("claim_generator: {generator} (matched {matched}; {state_label})"),
                    300,
                ),
            )
            .with_tool(*tool),
        );
    }

    if let Some(info) = &manifest.claim_generator_info {
        for generator in info {
            let value = match &generator.version {
                Some(version) => format!("{} {}", generator.name, version),
                None => generator.name.clone(),
            };
            if let Some((tool, matched)) = patterns::match_value(&value).first() {
                signals.push(
                    Signal::new(
                        Source::C2pa,
                        confidence_for(85, state),
                        "c2pa.claim_generator_info",
                        patterns::truncate(
                            &format!(
                                "claim_generator_info: {value} (matched {matched}; {state_label})"
                            ),
                            300,
                        ),
                    )
                    .with_tool(*tool),
                );
            }
        }
    }

    for label in [Actions::LABEL, Actions::LABEL_VERSIONED] {
        let Ok(actions) = manifest.find_assertion::<Actions>(label) else {
            continue;
        };
        for action in actions.actions() {
            let software = action
                .software_agent()
                .and_then(|agent| serde_json::to_string(agent).ok());
            if let Some(source_type) = action.source_type()
                && let Some((weight, description)) = source_type_description(source_type)
            {
                let mut detail = format!(
                    "action {}; digitalSourceType {description}; {state_label}",
                    action.action()
                );
                if let Some(software) = &software {
                    detail.push_str(&format!("; softwareAgent {software}"));
                }
                let tool = software
                    .as_deref()
                    .and_then(|value| patterns::match_value(value).first().map(|(tool, _)| *tool))
                    .or_else(|| {
                        software.as_deref().and_then(|value| {
                            patterns::match_text(value).first().map(|(tool, _)| *tool)
                        })
                    });
                let mut signal = Signal::new(
                    Source::C2pa,
                    confidence_for(weight, state),
                    "c2pa.digital_source_type",
                    patterns::truncate(&detail, 400),
                );
                if let Some(tool) = tool {
                    signal = signal.with_tool(tool);
                }
                signals.push(signal);
            }
            if let Some(software) = &software
                && let Some((tool, matched)) = patterns::match_value(software).first()
            {
                signals.push(
                    Signal::new(
                        Source::C2pa,
                        confidence_for(80, state),
                        "c2pa.software_agent",
                        patterns::truncate(
                            &format!("softwareAgent {software} (matched {matched}; {state_label})"),
                            300,
                        ),
                    )
                    .with_tool(*tool),
                );
            }
        }
    }
}

/// Map C2PA's digital source type to a severity and description.
fn source_type_description(source_type: &DigitalSourceType) -> Option<(u8, &'static str)> {
    match source_type {
        DigitalSourceType::TrainedAlgorithmicMedia => {
            Some((95, "trainedAlgorithmicMedia (fully AI-generated)"))
        }
        DigitalSourceType::CompositeWithTrainedAlgorithmicMedia => Some((
            90,
            "compositeWithTrainedAlgorithmicMedia (contains AI-generated parts)",
        )),
        DigitalSourceType::CompositeSynthetic => {
            Some((82, "compositeSynthetic (contains synthetic parts)"))
        }
        DigitalSourceType::TrainedAlgorithmicData => {
            Some((70, "trainedAlgorithmicData (AI-generated data)"))
        }
        DigitalSourceType::AlgorithmicMedia => Some((
            60,
            "algorithmicMedia (algorithmic, not necessarily AI-trained)",
        )),
        DigitalSourceType::DataDrivenMedia => {
            Some((60, "dataDrivenMedia (data-driven generation)"))
        }
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn trained_media_maps_to_high_confidence() {
        let (weight, _) =
            source_type_description(&DigitalSourceType::TrainedAlgorithmicMedia).unwrap();
        assert_eq!(
            confidence_for(weight, ValidationState::Valid),
            Confidence::High
        );
        assert_eq!(
            confidence_for(weight, ValidationState::Invalid),
            Confidence::Medium
        );
    }

    #[test]
    fn plain_capture_is_not_ai() {
        assert!(source_type_description(&DigitalSourceType::DigitalCapture).is_none());
    }

    #[test]
    fn precheck_rejects_plain_bytes() {
        assert!(!may_have_c2pa(b"\x89PNG\r\n\x1a\n"));
        assert!(may_have_c2pa(b"....jumb...."));
    }
}
